import { lexer } from './lexer.js';
import {
  DepthLimitError,
  LexerError,
  ParserError,
  SyntaxParseError,
} from './exception.js';
import { parser } from './parser.js';
import { interpreter } from './interpreter.js';
import {
  ArrayClose,
  ArrayOpen,
  InlineTableClose,
  InlineTableOpen,
} from './tokens/index.js';

// Real-world TOML nesting is single-digit deep. The default sits safely below the
// native V8 stack-overflow threshold so the limit fires deterministically before the
// recursive parser/interpreter can overflow, while staying far above any legitimate
// document. Callers needing deeper input can raise it via `maxDepth`.
export const DEFAULT_MAX_DEPTH = 100;

export interface LoadOptions {
  maxDepth?: number;
}

// Bound array / inline-table nesting by scanning the token stream before the recursive
// parser runs, so nesting can never drive the parser past the native call stack.
const checkNestingDepth = (
  tokens: ReturnType<typeof lexer.tokenize>['tokens'],
  maxDepth: number
): void => {
  let depth = 0;
  for (const token of tokens) {
    const type = token.tokenType;
    if (type === ArrayOpen || type === InlineTableOpen) {
      depth += 1;
      if (depth > maxDepth) {
        throw new DepthLimitError(maxDepth);
      }
    } else if (type === ArrayClose || type === InlineTableClose) {
      depth -= 1;
    }
  }
};

export const load = (
  toml: string,
  options?: LoadOptions
): Record<string, unknown> => {
  const maxDepth =
    options?.maxDepth && options.maxDepth > 0
      ? options.maxDepth
      : DEFAULT_MAX_DEPTH;

  const lexingResult = lexer.tokenize(toml);

  if (lexingResult.errors.length > 0) {
    throw new LexerError(lexingResult.errors);
  }

  checkNestingDepth(lexingResult.tokens, maxDepth);

  try {
    parser.input = lexingResult.tokens;
    const cst = parser.toml();

    if (parser.errors.length > 0) {
      throw new ParserError(parser.errors);
    }

    interpreter.maxDepth = maxDepth;
    return interpreter.visit(cst);
  } catch (error) {
    // Backstop: convert any residual native stack exhaustion (e.g. on a constrained
    // stack, or when maxDepth is raised beyond the environment's native capacity) into
    // the documented SyntaxParseError contract. Library errors already extend
    // SyntaxParseError and pass through unchanged.
    if (error instanceof RangeError) {
      throw new SyntaxParseError(
        'Maximum nesting depth exceeded (stack overflow)'
      );
    }
    throw error;
  }
};

import { parser } from './parser.js';
import { DepthLimitError, InterpreterError } from './exception.js';
import { TokenType } from 'chevrotain';
import { tokenInterpreters } from './tokens/tokenInterpreters.js';
import { Boolean, SimpleKey, TomlString } from './tokens/index.js';
import { Float } from './tokens/Float.js';
import { DateTime } from './tokens/DateTime.js';
import { Integer } from './tokens/Integer.js';
import { isPlainObject } from '../common/utils.js';

// Create a safe object without prototype pollution vulnerability
const createSafeObject = () => Object.create(null);

// Helper functions to safely handle symbols on objects created with Object.create(null)
const setSymbol = (obj: unknown, symbol: symbol, value: unknown) => {
  (obj as Record<symbol, unknown>)[symbol] = value;
};

const hasSymbol = (obj: unknown, symbol: symbol): boolean => {
  return symbol in (obj as Record<symbol, unknown>);
};

class DuplicateKeyError extends Error {}

const tryCreateKey = (operation, message) => {
  try {
    return operation();
  } catch (error) {
    if (error instanceof DuplicateKeyError) {
      throw new InterpreterError(message);
    }
    /* v8 ignore next -- defensive rethrow for non-DuplicateKeyError exceptions */
    throw error;
  }
};

const BaseCstVisitor = parser.getBaseCstVisitorConstructor();

const explicitlyDeclared = Symbol('explicitlyDeclared');
const implicitlyDeclared = Symbol('implicitlyDeclared');

const notEditable = Symbol('notEditable');

export class Interpreter extends BaseCstVisitor {
  // Maximum dotted-key / table-header depth. Bounds the per-segment recursion in
  // assignValue/createTable/getOrCreateArray. Set by load() per call; defaults to
  // unbounded so direct interpreter use stays backward compatible.
  maxDepth = Number.POSITIVE_INFINITY;

  constructor() {
    super();
    this.validateVisitor();
  }

  toml(ctx) {
    const root = createSafeObject();
    let current = root;
    ctx.expression?.forEach(
      (expression) => (current = this.visit(expression, { current, root }))
    );
    this.cleanInternalProperties(root);
    return root;
  }

  expression(ctx, { current, root }) {
    if (ctx.keyValue) {
      this.visit(ctx.keyValue, current);
      return current;
    } else if (ctx.table) {
      return this.visit(ctx.table, root);
    }
  }

  keyValue(ctx, object) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);
    const value = this.visit(ctx.value);

    tryCreateKey(
      () => this.assignValue(keys, value, object),
      `Cannot assign value to '${keys.join('.')}'`
    );
  }

  key(ctx) {
    if (ctx.dottedKey) {
      return this.visit(ctx.dottedKey);
    } else {
      return [this.interpret(ctx, SimpleKey)];
    }
  }

  dottedKey(ctx) {
    return this.interpret(ctx, SimpleKey);
  }

  inlineTableKeyValues(ctx, object) {
    if (ctx.keyValue) {
      ctx.keyValue.forEach((keyValue) => this.visit(keyValue, object));
    }
  }

  inlineTable(ctx) {
    const result = createSafeObject();
    setSymbol(result, notEditable, true);
    if (ctx.inlineTableKeyValues) {
      this.visit(ctx.inlineTableKeyValues, result);
    }

    return result;
  }

  value(ctx) {
    if (ctx.array) {
      return this.visit(ctx.array);
    } else if (ctx.inlineTable) {
      return this.visit(ctx.inlineTable);
    }

    return this.interpret(ctx, TomlString, Float, Boolean, DateTime, Integer);
  }

  arrayValues(ctx, array) {
    ctx.value.forEach((value) => array.push(this.visit(value)));
    return array;
  }

  array(ctx) {
    const result = [];
    setSymbol(result, notEditable, true);
    if (ctx.arrayValues) {
      return this.visit(ctx.arrayValues, result);
    }

    return result;
  }

  table(ctx, root) {
    if (ctx.stdTable) {
      return this.visit(ctx.stdTable, root);
    } else if (ctx.arrayTable) {
      return this.visit(ctx.arrayTable, root);
    }
  }

  stdTable(ctx, root) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);

    return tryCreateKey(
      () => this.createTable(keys, root),
      `Cannot create table '${keys.join('.')}'`
    );
  }

  arrayTable(ctx, root) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);
    return tryCreateKey(
      () => {
        const array = this.getOrCreateArray(keys, root);
        if (hasSymbol(array, notEditable)) {
          throw new DuplicateKeyError();
        }

        const object = createSafeObject();
        array.push(object);
        return object;
      },
      `Cannot create array table '${keys.join('.')}'`
    );
  }

  private checkKeyDepth(keys) {
    if (keys.length > this.maxDepth) {
      throw new DepthLimitError(this.maxDepth);
    }
  }

  private cleanInternalProperties(object) {
    for (const symbol of Object.getOwnPropertySymbols(object)) {
      delete object[symbol];
    }
    for (const key in object) {
      if (Array.isArray(object[key])) {
        for (const symbol of Object.getOwnPropertySymbols(object[key])) {
          delete object[key][symbol];
        }
        object[key].forEach((item) => this.cleanInternalProperties(item));
      } else if (typeof object[key] === 'object') {
        this.cleanInternalProperties(object[key]);
      }
    }
  }

  private interpret(ctx, ...candidates: TokenType[]) {
    for (const type of candidates) {
      if (ctx[type.name]) {
        const interpret = tokenInterpreters.get(type.name);
        const result = ctx[type.name].map((token) =>
          interpret(token.image, token, type.name)
        );

        return result.length === 1 ? result[0] : result;
      }
    }
  }

  private assignPrimitiveValue(key, value, object) {
    if (key in object) {
      throw new DuplicateKeyError();
    }
    if (isPlainObject(value)) {
      setSymbol(value, explicitlyDeclared, true);
    }

    object[key] = value;
    return object;
  }

  private tryCreatingObject(
    key,
    object,
    declareSymbol,
    ignoreImplicitDeclared,
    ignoreExplicitDeclared
  ) {
    if (key in object) {
      if (
        !isPlainObject(object[key]) ||
        (!ignoreExplicitDeclared &&
          hasSymbol(object[key], explicitlyDeclared)) ||
        (!ignoreImplicitDeclared &&
          hasSymbol(object[key], implicitlyDeclared)) ||
        hasSymbol(object[key], notEditable)
      ) {
        throw new DuplicateKeyError();
      }
    } else {
      object[key] = createSafeObject();
      if (declareSymbol) {
        setSymbol(object[key], declareSymbol, true);
      }
    }

    return object[key];
  }

  private assignValue(keys, value, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      this.tryCreatingObject(first, object, implicitlyDeclared, true, false);
      return this.assignValue(keys, value, object[first], idx + 1);
    }

    return this.assignPrimitiveValue(first, value, object);
  }

  private createTable(keys, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      if (Array.isArray(object[first])) {
        if (hasSymbol(object[first], notEditable)) {
          throw new DuplicateKeyError();
        }
        const toAdd = object[first][object[first].length - 1];
        return this.createTable(keys, toAdd, idx + 1);
      }
      this.tryCreatingObject(first, object, null, true, true);
      return this.createTable(keys, object[first], idx + 1);
    }
    return this.tryCreatingObject(
      first,
      object,
      explicitlyDeclared,
      false,
      false
    );
  }

  private getOrCreateArray(keys, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      if (Array.isArray(object[first])) {
        if (hasSymbol(object[first], notEditable)) {
          throw new DuplicateKeyError();
        }
        const toAdd = object[first][object[first].length - 1];
        return this.getOrCreateArray(keys, toAdd, idx + 1);
      }
      this.tryCreatingObject(first, object, null, true, true);
      return this.getOrCreateArray(keys, object[first], idx + 1);
    }

    if (first in object && !Array.isArray(object[first])) {
      throw new DuplicateKeyError();
    }

    object[first] = object[first] || [];
    return object[first];
  }
}

export const interpreter = new Interpreter();

import { ILexingError, IRecognitionException } from 'chevrotain';

export class SyntaxParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SyntaxParseError';
  }
}

export class LexerError extends SyntaxParseError {
  errors: ILexingError[];

  constructor(errors: ILexingError[]) {
    super('Syntax error\n' + errors.map((error) => error.message).join('\n'));
    this.errors = errors;
  }
}

export class ParserError extends SyntaxParseError {
  errors: IRecognitionException[];

  constructor(errors: IRecognitionException[]) {
    super('Syntax error\n' + errors.map((error) => error.message).join('\n'));
    this.errors = errors;
  }
}

export class InterpreterError extends SyntaxParseError {
  constructor(message: string) {
    super(message);
  }
}

export class DepthLimitError extends SyntaxParseError {
  constructor(maxDepth: number) {
    super(`Maximum nesting depth of ${maxDepth} exceeded`);
  }
}

import { describe, it, expect } from 'vitest';
import { load, SyntaxParseError } from '../src/index.js';

describe('Security', () => {
  describe('Radix-prefixed integer literal length cap', () => {
    // Each of these inputs would, on an unpatched build, run the hand-written
    // `parseBigInt` loop `O(n^2)` times.  With the 1000-digit cap they are
    // rejected at the interpreter callsite in microseconds.
    it('should reject 0x literals longer than 1000 hex digits', () => {
      const toml = `x = 0x${'f'.repeat(1001)}`;
      expect(() => load(toml)).toThrow(SyntaxParseError);
    });

    it('should reject 0o literals longer than 1000 octal digits', () => {
      const toml = `x = 0o${'7'.repeat(1001)}`;
      expect(() => load(toml)).toThrow(SyntaxParseError);
    });

    it('should reject 0b literals longer than 1000 binary digits', () => {
      const toml = `x = 0b${'1'.repeat(1001)}`;
      expect(() => load(toml)).toThrow(SyntaxParseError);
    });

    it('should accept 0x literals up to the 1000-digit cap', () => {
      const toml = `x = 0x${'1'.repeat(1000)}`;
      const result = load(toml) as { x: bigint };
      // 4 bits per hex digit, leading `1` so result has 1000*4 - 3 bits set
      expect(typeof result.x).toBe('bigint');
      expect(result.x.toString(16)).toBe('1'.repeat(1000));
    });

    it('should reject the literal in microseconds, not seconds', () => {
      const toml = `x = 0x${'f'.repeat(50_000)}`;
      const t0 = process.hrtime.bigint();
      expect(() => load(toml)).toThrow(SyntaxParseError);
      const elapsedMs = Number(process.hrtime.bigint() - t0) / 1e6;
      // Unpatched build needs ~200 ms here; the cap should make it < 50 ms
      // even on slow CI runners.
      expect(elapsedMs).toBeLessThan(500);
    });
  });

  describe('Falsy-primitive duplicate-key bypass (GHSA-m34p-749j-x6m6)', () => {
    // A falsy-typed value (false, 0, 0.0, -0.0, nan, "") followed by a table,
    // dotted-key sub-table, or array-of-tables sharing the same name must be a
    // duplicate-key parse error, not a silent overwrite. The interpreter used
    // `if (object[key])` (truthy test) instead of `if (key in object)`.
    const falsyValues = [
      'false',
      '0',
      '0x0',
      '0o0',
      '0b0',
      '0.0',
      '-0.0',
      'nan',
      '""',
    ];

    it('should reject the advisory PoC (boolean false shadowed by a table)', () => {
      const toml = `isAdmin = false\n[isAdmin]\nforced = "yes"`;
      expect(() => load(toml)).toThrow(SyntaxParseError);
    });

    falsyValues.forEach((value) => {
      it(`should reject a [stdTable] redefining a key valued ${value}`, () => {
        expect(() => load(`k = ${value}\n[k]\nx = 1`)).toThrow(
          SyntaxParseError
        );
      });

      it(`should reject a dotted-key sub-table over a key valued ${value}`, () => {
        expect(() => load(`k = ${value}\nk.b = "x"`)).toThrow(SyntaxParseError);
      });

      it(`should reject an array-of-tables over a key valued ${value}`, () => {
        expect(() => load(`k = ${value}\n[[k]]\nb = 1`)).toThrow(
          SyntaxParseError
        );
      });
    });

    it('should still accept a single falsy primitive value', () => {
      expect(load('k = false')).toEqual({ k: false });
      expect(load('k = 0')).toEqual({ k: 0 });
      expect(load('k = ""')).toEqual({ k: '' });
    });

    it('should still accept a falsy value alongside an unrelated table', () => {
      const result = load(`flag = false\n[other]\nx = 1`);
      expect(result).toEqual({ flag: false, other: { x: 1 } });
    });
  });

  describe('Prototype Pollution Prevention', () => {
    it('should not allow __proto__ pollution', () => {
      const toml = `
[__proto__]
polluted = true
`;

      const result = load(toml);

      const testObj = {};
      expect('polluted' in testObj).toBe(false);
      expect('polluted' in Object.prototype).toBe(false);

      expect(result).toHaveProperty('__proto__');
      expect(result['__proto__']).toHaveProperty('polluted', true);
    });

    it('should not allow constructor pollution', () => {
      const toml = `
[constructor]
[constructor.prototype]
polluted = true
`;

      const result = load(toml);

      const testObj = {};
      expect('polluted' in testObj).toBe(false);
      expect('polluted' in Object.prototype).toBe(false);

      expect(result).toHaveProperty('constructor');
    });

    it('should reproduce the authentication bypass scenario', () => {
      const toml = `
[__proto__]
isAdmin = true
`;

      // Simulate the vulnerable authentication function
      const isAdmin = (user: Record<string, unknown>) => {
        return user.isAdmin === true;
      };

      // Parse the malicious TOML
      load(toml);

      // Create a user object that should not be admin
      const user = { username: 'foo' };

      // This should return false (user is not admin)
      // If prototype pollution occurred, this would return true
      expect(isAdmin(user)).toBe(false);
      expect('isAdmin' in user).toBe(false);
    });

    it('should handle dotted __proto__ keys safely', () => {
      const toml = `
[table.__proto__]
polluted = true
`;

      const result = load(toml);

      const testObj = {};
      expect('polluted' in testObj).toBe(false);
      expect('polluted' in Object.prototype).toBe(false);

      expect('table' in result).toBe(true);
      expect('__proto__' in result['table']).toBe(true);
    });

    it('should handle inline table __proto__ safely', () => {
      const toml = `
obj = { __proto__ = { polluted = true } }
`;

      const result = load(toml);

      const testObj = {};
      expect('polluted' in testObj).toBe(false);
      expect('polluted' in Object.prototype).toBe(false);

      expect(result).toHaveProperty('obj');
    });
  });

  it('should not allow pollution via array of tables syntax', () => {
    const toml = `
[[__proto__]]
polluted = true
`;
    const result = load(toml);

    expect('polluted' in Object.prototype).toBe(false);
    expect('polluted' in Array.prototype).toBe(false);

    expect(result).toHaveProperty('__proto__');
    expect(Array.isArray(result['__proto__'])).toBe(true);
    expect(result['__proto__'][0]).toEqual({ polluted: true });
  });

  it('should handle deeply nested __proto__ keys safely', () => {
    const toml = `
[a.b.__proto__.c]
polluted = true
`;
    const result = load(toml);

    const testObj = {};
    expect('polluted' in testObj).toBe(false);

    const resultObj = result as Record<
      string,
      Record<string, Record<string, Record<string, unknown>>>
    >;
    expect(resultObj.a.b['__proto__'].c).toEqual({ polluted: true });
  });

  it('should treat "prototype" as a regular key', () => {
    const toml = `
[prototype]
polluted = true
`;
    const result = load(toml);

    const testObj = {};
    expect('polluted' in testObj).toBe(false);

    expect(result).toHaveProperty('prototype');
    expect(result['prototype']).toEqual({ polluted: true });
  });

  describe('Recursion depth limit (GHSA-3g82-77xr-68x5)', () => {
    // Deeply nested input or a long dotted key must NOT drive recursion past the V8
    // call stack and surface a raw RangeError. It must be rejected as a
    // SyntaxParseError, preserving the documented error contract.

    const deepArray = (n: number) => 'x = ' + '['.repeat(n) + ']'.repeat(n);
    const deepInlineTable = (n: number) => {
      let v = '1';
      for (let i = 0; i < n; i++) v = `{ a = ${v} }`;
      return 'x = ' + v;
    };
    const deepDottedKey = (n: number) =>
      Array.from({ length: n }, (_, i) => 'a' + i).join('.') + ' = 1';

    it('should reject deeply nested arrays as SyntaxParseError, not RangeError', () => {
      expect(() => load(deepArray(1000))).toThrow(SyntaxParseError);
      expect(() => load(deepArray(1000))).not.toThrow(RangeError);
    });

    it('should reject deeply nested inline tables as SyntaxParseError, not RangeError', () => {
      expect(() => load(deepInlineTable(1000))).toThrow(SyntaxParseError);
      expect(() => load(deepInlineTable(1000))).not.toThrow(RangeError);
    });

    it('should reject deep dotted keys as SyntaxParseError, not RangeError', () => {
      expect(() => load(deepDottedKey(5000))).toThrow(SyntaxParseError);
      expect(() => load(deepDottedKey(5000))).not.toThrow(RangeError);
    });

    it('should accept documents within the default depth limit', () => {
      expect(load(deepArray(50))).toEqual({
        x: expect.anything(),
      });
      const dotted = load(deepDottedKey(50)) as Record<string, unknown>;
      expect(dotted).toHaveProperty('a0');
    });

    it('should accept depth that a raised maxDepth permits', () => {
      // depth 200 exceeds the default (100) but is allowed with maxDepth 500
      expect(() => load(deepArray(200))).toThrow(SyntaxParseError);
      expect(() => load(deepArray(200), { maxDepth: 500 })).not.toThrow();
      expect(() => load(deepDottedKey(200), { maxDepth: 500 })).not.toThrow();
    });

    it('should reject depth that a lowered maxDepth forbids', () => {
      // depth 30 is fine by default but rejected with maxDepth 10
      expect(() => load(deepArray(30))).not.toThrow();
      expect(() => load(deepArray(30), { maxDepth: 10 })).toThrow(
        SyntaxParseError
      );
    });

    it('should never leak a RangeError even when maxDepth exceeds native capacity', () => {
      // Pre-scan passes (depth 1000 < 5000) but the native stack overflows first;
      // the top-level backstop must still surface a SyntaxParseError.
      expect(() => load(deepInlineTable(1000), { maxDepth: 5000 })).toThrow(
        SyntaxParseError
      );
      expect(() => load(deepInlineTable(1000), { maxDepth: 5000 })).not.toThrow(
        RangeError
      );
    });
  });
});

