// Cap the digit length of `0x` / `0o` / `0b` integer literals.
//
// The previous hand-written `parseBigInt` loop performed
// `result = result * BigInt(radix) + BigInt(digit)` once per input digit, so
// the per-iteration cost grew linearly with the number of digits already
// consumed and the whole loop was `O(n^2)`. Switching to the V8 native
// `BigInt(prefixedString)` constructor brings the per-call cost down to
// `O(n)`, but a multi-megabyte literal can still tie up the event loop on a
// single document, so we also cap the literal length up front. 1000 matches
// the `jackson-core` `StreamReadConstraints.maxNumberLength` default.
const MAX_RADIX_LITERAL_LENGTH = 1000;

const getRadix = (raw: string): number => {
  switch (raw.slice(0, 2) as '0x' | '0o' | '0b') {
    case '0x':
      return 16;
    case '0o':
      return 8;
    case '0b':
      return 2;
  }
};

registerTokenInterpreter(NonDecimalInteger, (raw: string) => {
  const intString = raw.replace(/_/g, '');
  const digits = intString.slice(2);
  const radix = getRadix(raw);

  if (digits.length > MAX_RADIX_LITERAL_LENGTH) {
    throw new SyntaxParseError(
      `Radix-prefixed integer literal exceeds ${MAX_RADIX_LITERAL_LENGTH} digits (length ${digits.length})`
    );
  }

  const int = parseInt(digits, radix);

  if (Number.isSafeInteger(int)) {
    return int;
  }

  // `BigInt` natively accepts the `0x` / `0o` / `0b` prefix and parses in O(n).
  return BigInt(intString);
});

import { createToken, IToken, Lexer, TokenType } from 'chevrotain';

export type InterpreterFunc = (
  raw: string,
  token: IToken,
  category: string
) => string | boolean | number | bigint | Date;

export const tokenInterpreters = new Map<string, InterpreterFunc>();

export const defaultFallbackInterpreter: InterpreterFunc = (
  raw,
  token,
  category
) => {
  const interpreter = tokenInterpreters.get(token.tokenType.name);
  if (interpreter) {
    return interpreter(raw, token, category);
  }
};

export const registerTokenInterpreter = (
  token: TokenType,
  interpreter: InterpreterFunc
) => {
  tokenInterpreters.set(token.name, interpreter);
};

export const createCategoryToken = (name: string, categories?: TokenType[]) => {
  const token = createToken({
    name,
    pattern: Lexer.NA,
    ...(categories && { categories }),
  });
  registerTokenInterpreter(token, defaultFallbackInterpreter);
  return token;
};

import { lexer } from './lexer.js';
import {
  DepthLimitError,
  LexerError,
  ParserError,
  SyntaxParseError,
} from './exception.js';
import { parser } from './parser.js';
import { interpreter } from './interpreter.js';
import {
  ArrayClose,
  ArrayOpen,
  InlineTableClose,
  InlineTableOpen,
} from './tokens/index.js';

// Real-world TOML nesting is single-digit deep. The default sits safely below the
// native V8 stack-overflow threshold so the limit fires deterministically before the
// recursive parser/interpreter can overflow, while staying far above any legitimate
// document. Callers needing deeper input can raise it via `maxDepth`.
export const DEFAULT_MAX_DEPTH = 100;

export interface LoadOptions {
  maxDepth?: number;
}

// Bound array / inline-table nesting by scanning the token stream before the recursive
// parser runs, so nesting can never drive the parser past the native call stack.
const checkNestingDepth = (
  tokens: ReturnType<typeof lexer.tokenize>['tokens'],
  maxDepth: number
): void => {
  let depth = 0;
  for (const token of tokens) {
    const type = token.tokenType;
    if (type === ArrayOpen || type === InlineTableOpen) {
      depth += 1;
      if (depth > maxDepth) {
        throw new DepthLimitError(maxDepth);
      }
    } else if (type === ArrayClose || type === InlineTableClose) {
      depth -= 1;
    }
  }
};

export const load = (
  toml: string,
  options?: LoadOptions
): Record<string, unknown> => {
  const maxDepth =
    options?.maxDepth && options.maxDepth > 0
      ? options.maxDepth
      : DEFAULT_MAX_DEPTH;

  const lexingResult = lexer.tokenize(toml);

  if (lexingResult.errors.length > 0) {
    throw new LexerError(lexingResult.errors);
  }

  checkNestingDepth(lexingResult.tokens, maxDepth);

  try {
    parser.input = lexingResult.tokens;
    const cst = parser.toml();

    if (parser.errors.length > 0) {
      throw new ParserError(parser.errors);
    }

    interpreter.maxDepth = maxDepth;
    return interpreter.visit(cst);
  } catch (error) {
    // Backstop: convert any residual native stack exhaustion (e.g. on a constrained
    // stack, or when maxDepth is raised beyond the environment's native capacity) into
    // the documented SyntaxParseError contract. Library errors already extend
    // SyntaxParseError and pass through unchanged.
    if (error instanceof RangeError) {
      throw new SyntaxParseError(
        'Maximum nesting depth exceeded (stack overflow)'
      );
    }
    throw error;
  }
};

import { ILexingError, IRecognitionException } from 'chevrotain';

export class SyntaxParseError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'SyntaxParseError';
  }
}

export class LexerError extends SyntaxParseError {
  errors: ILexingError[];

  constructor(errors: ILexingError[]) {
    super('Syntax error\n' + errors.map((error) => error.message).join('\n'));
    this.errors = errors;
  }
}

export class ParserError extends SyntaxParseError {
  errors: IRecognitionException[];

  constructor(errors: IRecognitionException[]) {
    super('Syntax error\n' + errors.map((error) => error.message).join('\n'));
    this.errors = errors;
  }
}

export class InterpreterError extends SyntaxParseError {
  constructor(message: string) {
    super(message);
  }
}

export class DepthLimitError extends SyntaxParseError {
  constructor(maxDepth: number) {
    super(`Maximum nesting depth of ${maxDepth} exceeded`);
  }
}

import { parser } from './parser.js';
import { DepthLimitError, InterpreterError } from './exception.js';
import { TokenType } from 'chevrotain';
import { tokenInterpreters } from './tokens/tokenInterpreters.js';
import { Boolean, SimpleKey, TomlString } from './tokens/index.js';
import { Float } from './tokens/Float.js';
import { DateTime } from './tokens/DateTime.js';
import { Integer } from './tokens/Integer.js';
import { isPlainObject } from '../common/utils.js';

// Create a safe object without prototype pollution vulnerability
const createSafeObject = () => Object.create(null);

// Helper functions to safely handle symbols on objects created with Object.create(null)
const setSymbol = (obj: unknown, symbol: symbol, value: unknown) => {
  (obj as Record<symbol, unknown>)[symbol] = value;
};

const hasSymbol = (obj: unknown, symbol: symbol): boolean => {
  return symbol in (obj as Record<symbol, unknown>);
};

class DuplicateKeyError extends Error {}

const tryCreateKey = (operation, message) => {
  try {
    return operation();
  } catch (error) {
    if (error instanceof DuplicateKeyError) {
      throw new InterpreterError(message);
    }
    /* v8 ignore next -- defensive rethrow for non-DuplicateKeyError exceptions */
    throw error;
  }
};

const BaseCstVisitor = parser.getBaseCstVisitorConstructor();

const explicitlyDeclared = Symbol('explicitlyDeclared');
const implicitlyDeclared = Symbol('implicitlyDeclared');

const notEditable = Symbol('notEditable');

export class Interpreter extends BaseCstVisitor {
  // Maximum dotted-key / table-header depth. Bounds the per-segment recursion in
  // assignValue/createTable/getOrCreateArray. Set by load() per call; defaults to
  // unbounded so direct interpreter use stays backward compatible.
  maxDepth = Number.POSITIVE_INFINITY;

  constructor() {
    super();
    this.validateVisitor();
  }

  toml(ctx) {
    const root = createSafeObject();
    let current = root;
    ctx.expression?.forEach(
      (expression) => (current = this.visit(expression, { current, root }))
    );
    this.cleanInternalProperties(root);
    return root;
  }

  expression(ctx, { current, root }) {
    if (ctx.keyValue) {
      this.visit(ctx.keyValue, current);
      return current;
    } else if (ctx.table) {
      return this.visit(ctx.table, root);
    }
  }

  keyValue(ctx, object) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);
    const value = this.visit(ctx.value);

    tryCreateKey(
      () => this.assignValue(keys, value, object),
      `Cannot assign value to '${keys.join('.')}'`
    );
  }

  key(ctx) {
    if (ctx.dottedKey) {
      return this.visit(ctx.dottedKey);
    } else {
      return [this.interpret(ctx, SimpleKey)];
    }
  }

  dottedKey(ctx) {
    return this.interpret(ctx, SimpleKey);
  }

  inlineTableKeyValues(ctx, object) {
    if (ctx.keyValue) {
      ctx.keyValue.forEach((keyValue) => this.visit(keyValue, object));
    }
  }

  inlineTable(ctx) {
    const result = createSafeObject();
    setSymbol(result, notEditable, true);
    if (ctx.inlineTableKeyValues) {
      this.visit(ctx.inlineTableKeyValues, result);
    }

    return result;
  }

  value(ctx) {
    if (ctx.array) {
      return this.visit(ctx.array);
    } else if (ctx.inlineTable) {
      return this.visit(ctx.inlineTable);
    }

    return this.interpret(ctx, TomlString, Float, Boolean, DateTime, Integer);
  }

  arrayValues(ctx, array) {
    ctx.value.forEach((value) => array.push(this.visit(value)));
    return array;
  }

  array(ctx) {
    const result = [];
    setSymbol(result, notEditable, true);
    if (ctx.arrayValues) {
      return this.visit(ctx.arrayValues, result);
    }

    return result;
  }

  table(ctx, root) {
    if (ctx.stdTable) {
      return this.visit(ctx.stdTable, root);
    } else if (ctx.arrayTable) {
      return this.visit(ctx.arrayTable, root);
    }
  }

  stdTable(ctx, root) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);

    return tryCreateKey(
      () => this.createTable(keys, root),
      `Cannot create table '${keys.join('.')}'`
    );
  }

  arrayTable(ctx, root) {
    const keys = this.visit(ctx.key);
    this.checkKeyDepth(keys);
    return tryCreateKey(
      () => {
        const array = this.getOrCreateArray(keys, root);
        if (hasSymbol(array, notEditable)) {
          throw new DuplicateKeyError();
        }

        const object = createSafeObject();
        array.push(object);
        return object;
      },
      `Cannot create array table '${keys.join('.')}'`
    );
  }

  private checkKeyDepth(keys) {
    if (keys.length > this.maxDepth) {
      throw new DepthLimitError(this.maxDepth);
    }
  }

  private cleanInternalProperties(object) {
    for (const symbol of Object.getOwnPropertySymbols(object)) {
      delete object[symbol];
    }
    for (const key in object) {
      if (Array.isArray(object[key])) {
        for (const symbol of Object.getOwnPropertySymbols(object[key])) {
          delete object[key][symbol];
        }
        object[key].forEach((item) => this.cleanInternalProperties(item));
      } else if (typeof object[key] === 'object') {
        this.cleanInternalProperties(object[key]);
      }
    }
  }

  private interpret(ctx, ...candidates: TokenType[]) {
    for (const type of candidates) {
      if (ctx[type.name]) {
        const interpret = tokenInterpreters.get(type.name);
        const result = ctx[type.name].map((token) =>
          interpret(token.image, token, type.name)
        );

        return result.length === 1 ? result[0] : result;
      }
    }
  }

  private assignPrimitiveValue(key, value, object) {
    if (key in object) {
      throw new DuplicateKeyError();
    }
    if (isPlainObject(value)) {
      setSymbol(value, explicitlyDeclared, true);
    }

    object[key] = value;
    return object;
  }

  private tryCreatingObject(
    key,
    object,
    declareSymbol,
    ignoreImplicitDeclared,
    ignoreExplicitDeclared
  ) {
    if (key in object) {
      if (
        !isPlainObject(object[key]) ||
        (!ignoreExplicitDeclared &&
          hasSymbol(object[key], explicitlyDeclared)) ||
        (!ignoreImplicitDeclared &&
          hasSymbol(object[key], implicitlyDeclared)) ||
        hasSymbol(object[key], notEditable)
      ) {
        throw new DuplicateKeyError();
      }
    } else {
      object[key] = createSafeObject();
      if (declareSymbol) {
        setSymbol(object[key], declareSymbol, true);
      }
    }

    return object[key];
  }

  private assignValue(keys, value, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      this.tryCreatingObject(first, object, implicitlyDeclared, true, false);
      return this.assignValue(keys, value, object[first], idx + 1);
    }

    return this.assignPrimitiveValue(first, value, object);
  }

  private createTable(keys, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      if (Array.isArray(object[first])) {
        if (hasSymbol(object[first], notEditable)) {
          throw new DuplicateKeyError();
        }
        const toAdd = object[first][object[first].length - 1];
        return this.createTable(keys, toAdd, idx + 1);
      }
      this.tryCreatingObject(first, object, null, true, true);
      return this.createTable(keys, object[first], idx + 1);
    }
    return this.tryCreatingObject(
      first,
      object,
      explicitlyDeclared,
      false,
      false
    );
  }

  private getOrCreateArray(keys, object, idx = 0) {
    const first = keys[idx];
    if (idx < keys.length - 1) {
      if (Array.isArray(object[first])) {
        if (hasSymbol(object[first], notEditable)) {
          throw new DuplicateKeyError();
        }
        const toAdd = object[first][object[first].length - 1];
        return this.getOrCreateArray(keys, toAdd, idx + 1);
      }
      this.tryCreatingObject(first, object, null, true, true);
      return this.getOrCreateArray(keys, object[first], idx + 1);
    }

    if (first in object && !Array.isArray(object[first])) {
      throw new DuplicateKeyError();
    }

    object[first] = object[first] || [];
    return object[first];
  }
}

export const interpreter = new Interpreter();

import { CstNode, CstParser, IOrAlt, IToken } from 'chevrotain';
import {
  allTokens,
  ArrayClose,
  ArrayOpen,
  ArraySep,
  ArrayTableClose,
  ArrayTableOpen,
  Boolean,
  DateTime,
  DotSeparator,
  ExpressionNewLine,
  Float,
  InlineTableClose,
  InlineTableOpen,
  InlineTableSep,
  Integer,
  KeyValueSeparator,
  Newline,
  SimpleKey,
  StdTableClose,
  StdTableOpen,
  TomlString,
} from './tokens/index.js';
import { envs } from '../common/environment.js';

class Parser extends CstParser {
  toml = this.RULE('toml', () => {
    this.MANY(() => this.CONSUME(ExpressionNewLine));
    this.MANY1(() => {
      this.SUBRULE1(this.expression);
      this.OPTION2(() => {
        this.CONSUME1(Newline);
        this.MANY3(() => this.CONSUME2(ExpressionNewLine));
      });
    });
  });

  private valueCache: IOrAlt<IToken | CstNode>[];
  private dottedKey = this.RULE('dottedKey', () => {
    this.CONSUME(SimpleKey);
    this.AT_LEAST_ONE(() => {
      this.CONSUME(DotSeparator);
      this.CONSUME1(SimpleKey);
    });
  });
  private key = this.RULE('key', () => {
    this.OR({
      MAX_LOOKAHEAD: 2,
      DEF: [
        { ALT: () => this.SUBRULE(this.dottedKey) },
        { ALT: () => this.CONSUME(SimpleKey) },
      ],
    });
  });
  private inlineTableKeyValues = this.RULE('inlineTableKeyValues', () => {
    this.MANY_SEP({
      SEP: InlineTableSep,
      DEF: () => this.SUBRULE(this.keyValue),
    });
  });
  private inlineTable = this.RULE('inlineTable', () => {
    this.CONSUME(InlineTableOpen);
    this.OPTION(() => this.SUBRULE(this.inlineTableKeyValues));
    this.CONSUME(InlineTableClose);
  });
  private array = this.RULE('array', () => {
    this.CONSUME(ArrayOpen);
    this.OPTION(() => this.SUBRULE(this.arrayValues));
    this.CONSUME(ArrayClose);
  });
  private value = this.RULE('value', () => {
    this.OR(
      this.valueCache ||
        (this.valueCache = [
          { ALT: () => this.CONSUME(TomlString) },
          { ALT: () => this.CONSUME(Boolean) },
          { ALT: () => this.SUBRULE(this.array) },
          { ALT: () => this.SUBRULE(this.inlineTable) },
          { ALT: () => this.CONSUME(DateTime) },
          { ALT: () => this.CONSUME(Float) },
          { ALT: () => this.CONSUME(Integer) },
        ])
    );
  });
  private keyValue = this.RULE('keyValue', () => {
    this.SUBRULE(this.key);
    this.CONSUME(KeyValueSeparator);
    this.SUBRULE(this.value);
  });
  private arrayValues = this.RULE('arrayValues', () => {
    this.SUBRULE(this.value);
    let havingMore = true;
    this.MANY({
      GATE: () => havingMore,
      DEF: () => {
        this.CONSUME(ArraySep);
        const found = this.OPTION(() => this.SUBRULE1(this.value));
        if (!found) {
          havingMore = false;
        }
      },
    });
  });
  private stdTable = this.RULE('stdTable', () => {
    this.CONSUME(StdTableOpen);
    this.SUBRULE(this.key);
    this.CONSUME(StdTableClose);
  });
  private arrayTable = this.RULE('arrayTable', () => {
    this.CONSUME(ArrayTableOpen);
    this.SUBRULE(this.key);
    this.CONSUME(ArrayTableClose);
  });
  private table = this.RULE('table', () => {
    this.OR([
      { ALT: () => this.SUBRULE(this.stdTable) },
      { ALT: () => this.SUBRULE(this.arrayTable) },
    ]);
  });
  private expression = this.RULE('expression', () => {
    this.OR([
      { ALT: () => this.SUBRULE(this.keyValue) },
      { ALT: () => this.SUBRULE(this.table) },
    ]);
  });

  constructor() {
    super(allTokens, {
      traceInitPerf: envs.isDebug(),
      maxLookahead: 1,
      skipValidations: !envs.isDebug(),
    });
    this.performSelfAnalysis();
  }
}

export const parser = new Parser();

