{
  "name": "js-toml",
  "version": "1.1.3",
  "description": "A TOML parser for JavaScript/TypeScript, targeting TOML 1.0.0 Spec",
  "keywords": [
    "toml",
    "parser",
    "javascript",
    "typescript"
  ],
  "homepage": "https://github.com/sunnyadn/js-toml",
  "bugs": {
    "url": "https://github.com/sunnyadn/js-toml/issues",
    "email": "sunnyadn@foxmail.com"
  },
  "license": "MIT",
  "author": {
    "name": "Sunny Yang",
    "email": "sunnyadn@foxmail.com",
    "url": "https://www.linkedin.com/in/sunnyadn/"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/sunnyadn/js-toml.git"
  },
  "type": "module",
  "files": [
    "dist"
  ],
  "main": "./dist/index.cjs",
  "module": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": {
        "types": "./dist/index.d.ts",
        "default": "./dist/index.js"
      },
      "require": {
        "types": "./dist/index.d.cts",
        "default": "./dist/index.cjs"
      }
    }
  },
  "scripts": {
    "build": "tsup",
    "test": "vitest",
    "test:cov": "vitest --coverage",
    "diagram": "tsx script/generateDiagram.ts",
    "lint": "eslint .",
    "lint:fix": "eslint . --fix",
    "benchmark": "tsx benchmark/benchmark.ts"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.3",
    "@types/benchmark": "^2.1.5",
    "@types/node": "^25.3.0",
    "@vitest/coverage-v8": "^4.1.4",
    "benchmark": "^2.1.4",
    "esbuild": "^0.28.1",
    "eslint": "^9.39.3",
    "eslint-config-prettier": "^10.1.8",
    "eslint-plugin-prettier": "^5.5.5",
    "glob": "^13.0.6",
    "prettier": "^3.8.1",
    "timezone-mock": "^1.4.2",
    "tsup": "8.5.1",
    "tsx": "^4.21.0",
    "typescript": "^4.9.5",
    "typescript-eslint": "^8.56.1",
    "vitest": "^4.1.4"
  },
  "dependencies": {
    "chevrotain": "^12.0.0",
    "xregexp": "^5.1.2"
  },
  "packageManager": "pnpm@8.9.0"
}

